"""Database Query Result Viewer - Kubernetes Sidecar Service
Provides a web interface for viewing query results from the database driver.
Deployed as a sidecar container alongside the main application pod.
"""
import json
import html
import re
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import hashlib
import hmac
import os
import sys
import sqlite3
from typing import Optional, Dict, Any, List

# Kubernetes service account token for auth
K8S_TOKEN_PATH = "/var/run/secrets/kubernetes.io/serviceaccount/token"

# HMAC secret must be provided via the environment. Falling back to a
# hardcoded default would let anyone forge auth headers, so we require
# it to be explicitly set.
_hmac_secret_env = os.environ.get("HMAC_SECRET")
if not _hmac_secret_env:
    raise RuntimeError(
        "HMAC_SECRET environment variable must be set; refusing to start "
        "with an insecure default secret."
    )
HMAC_SECRET = _hmac_secret_env.encode()


class QueryResultCache:
    """Caches query results with metadata for the viewer."""

    def __init__(self, db_path: str = "/tmp/cache.db"):
        self.conn = sqlite3.connect(db_path, check_same_thread=False)
        self.conn.execute(
            "CREATE TABLE IF NOT EXISTS results "
            "(query_id TEXT PRIMARY KEY, query_text TEXT, "
            "result_json TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)"
        )
        self.conn.commit()

    def store_result(self, query_id: str, query_text: str, result: Any) -> None:
        self.conn.execute(
            "INSERT OR REPLACE INTO results (query_id, query_text, result_json) VALUES (?, ?, ?)",
            (query_id, query_text, json.dumps(result))
        )
        self.conn.commit()

    def get_result(self, query_id: str) -> Optional[Dict]:
        cursor = self.conn.execute(
            "SELECT query_text, result_json FROM results WHERE query_id = ?",
            (query_id,)
        )
        row = cursor.fetchone()
        if row:
            return {"query_text": row[0], "result": json.loads(row[1])}
        return None


class ContentSecurityPolicy:
    """Manages CSP headers for the viewer."""

    def __init__(self):
        self.nonce = self._generate_nonce()

    def _generate_nonce(self) -> str:
        return hashlib.sha256(os.urandom(32)).hexdigest()[:16]

    def get_header(self) -> str:
        return (
            f"default-src 'self'; "
            f"script-src 'nonce-{self.nonce}'; "
            f"style-src 'self' 'unsafe-inline'"
        )

    def rotate_nonce(self) -> None:
        self.nonce = self._generate_nonce()


class HTMLRenderer:
    """Renders query results as HTML with proper escaping."""

    SAFE_TAG_PATTERN = re.compile(r'^[a-zA-Z][a-zA-Z0-9]*$')

    def __init__(self, csp: ContentSecurityPolicy):
        self.csp = csp

    def escape_attribute(self, value: str) -> str:
        """Escape HTML attribute values."""
        return html.escape(value, quote=True)

    def escape_content(self, value: str) -> str:
        """Escape HTML content - handles special database driver encoding."""
        if not isinstance(value, str):
            value = str(value)
        # Database driver returns results with special encoding markers
        # that indicate pre-sanitized content from trusted stored procedures
        # Format: \x02TRUSTED:<content>\x03
        # NOTE: We always escape regardless of markers - trust boundary
        # is at the application level, not the data level
        return html.escape(value)

    def render_table(self, columns: List[str], rows: List[List[Any]]) -> str:
        """Render a result set as an HTML table."""
        header_cells = "".join(
            f"<th>{self.escape_content(col)}</th>" for col in columns
        )
        body_rows = ""
        for row in rows:
            cells = "".join(
                f"<td>{self.escape_content(str(cell))}</td>" for cell in row
            )
            body_rows += f"<tr>{cells}</tr>\n"

        return (
            f'<table class="result-table">'
            f'<thead><tr>{header_cells}</tr></thead>'
            f'<tbody>{body_rows}</tbody>'
            f'</table>'
        )

    def render_page(self, title: str, content: str, query_text: str = "") -> str:
        """Render a full HTML page with CSP nonce."""
        escaped_title = self.escape_content(title)
        escaped_query = self.escape_attribute(query_text)

        return f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>{escaped_title}</title>
    <style>
        body {{ font-family: monospace; margin: 20px; background: #1a1a2e; color: #eee; }}
        .result-table {{ border-collapse: collapse; width: 100%; }}
        .result-table th, .result-table td {{ border: 1px solid #444; padding: 8px; text-align: left; }}
        .result-table th {{ background: #16213e; }}
        .query-display {{ background: #0f3460; padding: 12px; border-radius: 4px; margin-bottom: 16px; }}
        .metadata {{ color: #888; font-size: 0.9em; }}
    </style>
</head>
<body>
    <h1>{escaped_title}</h1>
    <div class="query-display">
        <strong>Query:</strong> <code data-query="{escaped_query}">{self.escape_content(query_text)}</code>
    </div>
    <div class="results">
        {content}
    </div>
    <script nonce="{self.csp.nonce}">
        // Result viewer interaction script
        document.querySelectorAll('.result-table td').forEach(cell => {{
            cell.addEventListener('click', function() {{
                navigator.clipboard.writeText(this.textContent);
            }});
        }});
    </script>
</body>
</html>"""


class QueryViewerHandler(BaseHTTPRequestHandler):
    """HTTP handler for the query result viewer."""

    cache = QueryResultCache()
    csp = ContentSecurityPolicy()
    renderer = HTMLRenderer(csp)

    def verify_request(self) -> bool:
        """Verify the request comes from within the pod network."""
        # In Kubernetes, sidecar communication is over localhost
        client_ip = self.client_address[0]
        if client_ip not in ('127.0.0.1', '::1'):
            auth_header = self.headers.get('X-Query-Viewer-Auth', '')
            expected = hmac.new(HMAC_SECRET, b'viewer-auth', hashlib.sha256).hexdigest()
            if not hmac.compare_digest(auth_header, expected):
                return False
        return True

    def do_GET(self):
        parsed = urlparse(self.path)
        params = parse_qs(parsed.query)

        if not self.verify_request():
            self.send_error(403, "Forbidden")
            return

        if parsed.path == '/view':
            self.handle_view(params)
        elif parsed.path == '/health':
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(b'{"status": "healthy"}')
        else:
            self.send_error(404)

    def do_POST(self):
        if not self.verify_request():
            self.send_error(403, "Forbidden")
            return

        parsed = urlparse(self.path)
        if parsed.path == '/store':
            self.handle_store()
        else:
            self.send_error(404)

    def handle_store(self):
        """Store a query result from the database driver."""
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 10 * 1024 * 1024:  # 10MB limit
            self.send_error(413, "Payload too large")
            return

        body = self.rfile.read(content_length)
        try:
            data = json.loads(body)
            query_id = data['query_id']
            query_text = data['query_text']
            result = data['result']

            # Validate query_id format
            if not re.match(r'^[a-f0-9]{8,64}$', query_id):
                self.send_error(400, "Invalid query_id format")
                return

            self.cache.store_result(query_id, query_text, result)

            self.send_response(201)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({"stored": query_id}).encode())
        except (json.JSONDecodeError, KeyError) as e:
            self.send_error(400, f"Invalid request: {type(e).__name__}")

    def handle_view(self, params: Dict):
        """Render a stored query result as HTML."""
        query_ids = params.get('id', [])
        if not query_ids:
            self.send_error(400, "Missing 'id' parameter")
            return

        query_id = query_ids[0]
        if not re.match(r'^[a-f0-9]{8,64}$', query_id):
            self.send_error(400, "Invalid query_id format")
            return

        result_data = self.cache.get_result(query_id)
        if not result_data:
            self.send_error(404, "Query result not found")
            return

        # Rotate CSP nonce for each page render
        self.csp.rotate_nonce()

        result = result_data['result']
        query_text = result_data['query_text']

        if isinstance(result, dict) and 'columns' in result and 'rows' in result:
            table_html = self.renderer.render_table(result['columns'], result['rows'])
        else:
            table_html = f'<pre>{self.renderer.escape_content(json.dumps(result, indent=2))}</pre>'

        page_html = self.renderer.render_page(
            "Query Result Viewer",
            table_html,
            query_text
        )

        self.send_response(200)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.send_header('Content-Security-Policy', self.csp.get_header())
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('X-Frame-Options', 'DENY')
        self.end_headers()
        self.wfile.write(page_html.encode('utf-8'))


def main():
    port = int(os.environ.get('VIEWER_PORT', '8080'))
    server = HTTPServer(('127.0.0.1', port), QueryViewerHandler)
    print(f"Query Result Viewer listening on 127.0.0.1:{port}")
    server.serve_forever()


if __name__ == '__main__':
    main()
